namespace ghidra.app.plugin.core.datamgr.actions.associate;



using docking.action;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.util;

public class UpdateAction : SyncAction {
	public static readonly string MENU_NAME = "Update Data Types From";

	public UpdateAction(DataTypeManagerPlugin plugin, ArchiveManager dataTypeManagerHandler,
			DataTypeManager dtm, DataTypeStoreNode archiveNode, SourceArchive sourceArchive,
			bool isEnabled) : base("Update Data Types From Archive", plugin, dataTypeManagerHandler, dtm, archiveNode,
			sourceArchive, isEnabled)
    {

		setPopupMenuData(new MenuData(new string[] { MENU_NAME, sourceArchive.getName() }));
		setHelpLocation(new HelpLocation(plugin.getName(), getHelpTopic()));

	}

	/* @Override */
	protected int getMenuOrder() {
		return 1;
	}

	/* @Override */
	protected string getHelpTopic() {
		return "Update_Data_Types";
	}

	/* @Override */
	protected bool isAppropriateForAction(DataTypeSyncInfo info) {

		switch (info.getSyncState()) {
			case UPDATE:
			case CONFLICT:
				return true;
			default:
				return false;
		}
	}

	/* @Override */
	protected bool isPreselectedForAction(DataTypeSyncInfo info) {
		return info.getSyncState() == DataTypeSyncState.UPDATE;
	}

	/* @Override */
	protected string getOperationName() {
		return "Update";
	}

	/* @Override */
	protected void applyOperation(DataTypeSyncInfo info) {
		info.update();
	}

	/* @Override */
	protected string getConfirmationMessage(List<DataTypeSyncInfo> infos) {
		StringBuffer buf = new StringBuffer();
		if (containsConflicts(infos)) {
			buf.append("You are updating one or more conflicts which will OVERWRITE\n");
			buf.append("changes in this program or archive!\n\n");
		}
		buf.append("Are you sure you want to UPDATE " + infos.size() + " datatype(s)?");
		return buf.toString();
	}

	/* @Override */
	protected bool requiresArchiveOpenForEditing() {
		return false;
	}

	/* @Override */
	protected string getTitle(string sourceName, string clientName) {
		return "Update Datatype Changes From Archive \"" + sourceName + "\" To  \"" + clientName +
			"\"";
	}
}
